import {categories,fresh,scoreCategory,hidden,finish} from './engine.mjs';
const $=s=>document.querySelector(s), key='steadier-v1';let state=fresh(),storageOK=true,tab='home',ending=false,touched=false;
try{const raw=localStorage.getItem(key);if(raw){const s=JSON.parse(raw);if(s.version!==1||!Array.isArray(s.sessions)||!s.preferences)throw Error();state=s;}}catch{storageOK=false;}
const posts=[
 ['n1','Nature','The outside club','A small pause, outdoors','You don’t have to go far. A patch of sky, a familiar tree, a few minutes of fresh air. What did you notice today?','🌿'],
 ['m1','Music','Slow frequencies','Something to listen to','Today’s listening prompt: pick one familiar song and listen all the way through. No multitasking needed.','♫'],
 ['c1','Creativity','Make a little','Progress without pressure','A page of imperfect sketches still counts as a page of making. Here’s your invitation to create something just for you.','✺'],
 ['s1','Connection','Everyday people','Small moments of connection','Sent a friend a photo of something that reminded me of them. Sometimes that is enough of a conversation starter.','☀'],
 ['n2','News','Daily discussion','A busy news cycle','Another day of competing headlines and heated debate. This sample represents news and discussion content.',''],
 ['p1','Comparison','The highlight reel','Everyone’s big announcements','A new promotion. A dream holiday. Another perfect milestone. This sample represents curated achievement content.','']
].map(([id,category,author,title,body,art])=>({id,category,author,title,body,art}));
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{storageOK=false;toast('Storage unavailable. Keep this tab open; changes are temporary.');}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500);}
const avg=()=>state.sessions.length?Math.round(state.sessions.reduce((a,s)=>a+s.after-s.before,0)/state.sessions.length):null;
const signed=n=>n>0?'+'+n:String(n);
const date=n=>new Date(n).toLocaleDateString(undefined,{month:'short',day:'numeric'});
function stats(){return `<div class="stats"><div class="stat"><small>COMPLETED SESSIONS</small><strong>${state.sessions.length}</strong></div><div class="stat"><small>AVG. MOOD CHANGE</small><strong>${avg()===null?'—':signed(avg())}</strong></div><div class="stat"><small>CATEGORIES LEARNING</small><strong>${categories.filter(c=>scoreCategory(state,c).sessions>0).length}<small> / 6</small></strong></div></div>`;}
function side(){return `<div class="sidecards"><section class="card"><div class="leaf-art" aria-hidden="true">🌱</div><span class="eyebrow">SMALL STEPS, OVER TIME</span><h2 style="margin-top:12px">Your feed. Your pace.</h2><p class="sub">A little awareness can make room for a more intentional digital day.</p><div class="step"><b>1</b><div><h3>Check in with yourself</h3><p>A moment to notice how you feel.</p></div></div><div class="step"><b>2</b><div><h3>Explore, with intention</h3><p>You choose what feels right for you.</p></div></div><div class="step"><b>3</b><div><h3>Reflect & let it adapt</h3><p>Your feedback shapes future sessions.</p></div></div></section><section class="card"><h3>Always in your hands</h3><p class="note">Reveal any filtered post, change a preference, or delete your history. Check-ins stay in this browser.</p><button class="quiet" data-go="settings">Manage your preferences ↗</button><p class="note">Recovery-support prototype. It does not diagnose depression or replace your care plan.</p></section></div>`;}
function checkin(){const after=!!state.active;return `<section class="card checkin"><span class="eyebrow">${after?'AFTER YOUR SESSION':'BEFORE YOU BEGIN'}</span><h2 style="margin-top:15px">${after?'How are you feeling now?':'How are you arriving today?'}</h2><p class="sub">${after?'Take a breath. Check in with the same scale.':'There’s no right answer. Just a moment for yourself.'}</p><div class="mood"><span class="face" id="face">☺</span><strong id="mood-value">50</strong><small> / 100</small><div class="sub" id="mood-label">Somewhere in the middle</div></div><label for="mood" class="sub">Your current mood</label><input class="range" id="mood" type="range" min="0" max="100" value="50"><div class="ends"><span>0 · Very low</span><span>100 · Very good</span></div>${!state.consent?'<label class="consent"><input type="checkbox" id="consent">I agree to store my mood scores, viewed sample-post categories, and feedback on this device to personalise this demo.</label>':''}${after?'<label class="consent">Was this time well spent? <select id="worth"><option value="unsure">Not sure</option><option value="yes">Yes</option><option value="no">No</option></select></label>':''}<button class="primary wide" id="submit-mood" disabled>${after?'Save check-in & see my reflection':'Start my mindful session'} &nbsp; →</button><div class="row"><span class="note">Move the slider to confirm your score.</span><button class="quiet" id="skip">${after?'Continue browsing':'Explore without tracking'}</button></div></section>`;}
function home(){if(state.active&&!ending)return feed(true);return `<span class="eyebrow">YOUR DAILY MOMENT OF BALANCE</span><h1>A gentler way to scroll.</h1><p class="intro">Start with how you feel. Make a little space for what helps.</p><div class="grid"><div>${checkin()}<section class="card"><div class="row"><h3>Your journey, at a glance</h3><span class="badge">${state.sessions.length?'Your real check-ins':'A fresh start'}</span></div>${stats()}<button class="quiet" data-go="insights">Explore your mood insights ↗</button></section></div>${side()}</div>`;}
function feed(tracking){const ordered=[...posts].sort((a,b)=>scoreCategory(state,b.category).score-scoreCategory(state,a.category).score);return `<span class="eyebrow">${tracking?'SESSION IN PROGRESS':'UNTRACKED PREVIEW'}</span><h1>A little more of what helps.</h1><p class="intro">A sample social feed, shaped by your preferences. You’re always in control.</p><div class="grid"><section class="card"><div class="row feed-head"><h2>Your mindful feed</h2>${tracking?'<button class="primary" id="end">End session →</button>':'<button class="secondary" id="back">Back to check-in</button>'}</div><span class="note">Sample posts · Scroll to explore · Use “Mark as read” to include a post in your session.</span>${ordered.map(p=>postHTML(p,tracking)).join('')}</section><div><section class="card"><span class="eyebrow">${tracking?'YOU STARTED AT':'TAKE YOUR TIME'}</span><h2 style="margin-top:15px">${tracking?state.active.before+' / 100':'Just exploring'}</h2><p class="sub">${tracking?'When you’re ready, end your session to reflect on how you feel.':'Nothing in this preview is added to your mood history.'}</p><p class="note">Use End session before leaving. If you close the tab, your unfinished session will be here when you return.</p></section><section class="card"><h3>What shapes this feed?</h3><p class="note">Your preferences come first. Direct post feedback carries most weight. Mood patterns contribute gently after at least three relevant sessions.</p><button class="quiet" data-go="settings">Adjust filters ↗</button></section></div></div>`;}
function postHTML(p,tracking){const seen=state.active?.seen.some(x=>x.id===p.id),vote=state.active?.feedback[p.id];return `<article class="post" data-post="${p.id}">${hidden(state,p.category)?`<div class="filtered"><span>◌ &nbsp; A little breathing room</span><p>${p.category} content softened by your ${state.preferences[p.category]==='hide'?'preference':'learned filter'}.</p><button class="secondary reveal" data-id="${p.id}">Reveal this post</button></div><div class="post-content" hidden>`:'<div class="post-content">'}<div class="row"><div class="author"><div class="avatar">${p.author[0]}</div><div><strong>${p.author}</strong><small>${p.title}</small></div></div><span class="badge">${p.category}</span></div><p>${p.body}</p>${p.art?`<div class="post-art ${p.category.toLowerCase()}">${p.art}</div>`:''}${tracking?`<div class="feedback"><button class="read ${seen?'active':''}" data-id="${p.id}">${seen?'✓ Read':'Mark as read'}</button><button class="vote ${vote===1?'active':''}" data-id="${p.id}" data-value="1">↗ Felt helpful</button><button class="vote ${vote===-1?'active':''}" data-id="${p.id}" data-value="-1">↘ Felt unhelpful</button></div>`:''}</div></article>`;}
function insights(){const recent=state.sessions.slice(-8);return `<span class="eyebrow">NOTICE THE PATTERNS</span><h1>Your mood, over time.</h1><p class="intro">Small reflections, building a more personal picture.</p><div class="grid"><div><section class="card"><h2>Your check-in history</h2>${stats()}${recent.length?`<div class="trend">${recent.map(s=>`<div class="trend-item" title="${date(s.endedAt)}: ${s.before} before, ${s.after} after"><i style="height:${s.before}%"></i><i style="height:${s.after}%"></i><small>${date(s.endedAt)}</small></div>`).join('')}</div><p class="note">Light green: before · Dark green: after · Scale 0–100</p>`:'<div class="empty">Your first check-in is the beginning.<br>Complete a session to see your history here.</div>'}</section><section class="card"><h2>Session reflections</h2>${state.sessions.length?state.sessions.slice().reverse().map(s=>`<div class="history-item row"><div><strong>${date(s.endedAt)}</strong><p class="note">${s.seen.length} posts read · ${Math.max(1,Math.round((s.endedAt-s.startedAt)/60000))} min · Time well spent: ${s.worthwhile==='yes'?'Yes':s.worthwhile==='no'?'No':'Not sure'}</p></div><div>${s.before} → ${s.after}<p class="${s.after>=s.before?'positive':'negative'}">${signed(s.after-s.before)} points</p></div></div>`).join(''):'<p class="empty">No completed sessions yet.</p>'}</section></div><div><section class="card"><h2>What your feed is learning</h2><p class="note">These are associations and your feedback, not proof that a topic changed your mood.</p>${categories.map(c=>{const a=scoreCategory(state,c);return `<div class="category"><div class="row"><h3>${c}</h3><span class="badge">${hidden(state,c)?'Softened':a.score>.1?'Prioritised':'Balanced'}</span></div><div class="meter"><i style="width:${50+a.score*50}%"></i></div><span class="note">${a.sessions} sessions · ${a.votes} ratings</span></div>`;}).join('')}</section></div></div>`;}
function settings(){return `<span class="eyebrow">YOU SET THE BOUNDARIES</span><h1>Make this space yours.</h1><p class="intro">Personalisation should feel like a choice. Change yours at any time.</p><div class="grid"><section class="card"><h2>Content preferences</h2><p class="note">Adaptive learns from your feedback. Always show and Soften override learning. Softened posts can still be revealed.</p>${categories.map(c=>`<div class="category row"><div><h3>${c}</h3><span class="note">${scoreCategory(state,c).sessions} sessions to learn from</span></div><select aria-label="${c} preference" data-category="${c}">${[['adaptive','Adaptive'],['show','Always show'],['hide','Soften']].map(([v,l])=>`<option value="${v}" ${state.preferences[c]===v?'selected':''}>${l}</option>`).join('')}</select></div>`).join('')}</section><div><section class="card"><h2>Your data belongs to you.</h2><p class="note">Mood scores, session times, sample-post categories, and feedback are stored in this browser only. No social accounts are linked. Other people using this browser profile may be able to access this history.</p><button class="secondary" id="export">Export my data</button><p><button class="quiet" id="delete">Delete all data & reset</button></p><div id="delete-confirm"></div></section><section class="card"><h3>A support tool, with limits</h3><p class="note">Steadier is a prototype for reflection and personalisation. It has not been validated to prevent depression relapse. Mood changes have many causes; keep following the care plan agreed with your clinician.</p></section></div></div>`;}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('selected',b.dataset.tab===tab));$('#app').innerHTML=(!storageOK?'<p class="storage-warning">Device storage could not be read or saved. Your current changes may be temporary. Export your data before leaving.</p>':'')+(tab==='home'?home():tab==='insights'?insights():settings());bind();}
function navigate(t){tab=t;render();window.scrollTo(0,0);}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));const slider=$('#mood');if(slider){touched=false;const update=()=>{$('#submit-mood').disabled=!touched||(!state.consent&&!$('#consent')?.checked);};slider.oninput=()=>{touched=true;const n=+slider.value;$('#mood-value').textContent=n;$('#mood-label').textContent=n<25?'Feeling low':n<45?'A little below the middle':n<65?'Somewhere in the middle':n<85?'Feeling good':'Feeling very good';$('#face').textContent=n<35?'☁':n<65?'☺':'☀';update();};if($('#consent'))$('#consent').onchange=update;$('#submit-mood').onclick=()=>{if(!touched)return;if(!state.consent){if(!$('#consent').checked)return;state.consent=true;}if(state.active){const s=finish(state,+slider.value,$('#worth').value);ending=false;save();navigate('insights');toast(`Check-in saved. Mood change: ${signed(s.after-s.before)} points.`);}else{state.active={before:+slider.value,startedAt:Date.now(),seen:[],feedback:{}};save();render();}};$('#skip').onclick=()=>{if(state.active){ending=false;render();}else{$('#app').innerHTML=feed(false);bind();}};}
 if($('#end'))$('#end').onclick=()=>{ending=true;render();window.scrollTo(0,0);};if($('#back'))$('#back').onclick=()=>render();
 document.querySelectorAll('.reveal').forEach(b=>b.onclick=()=>{const article=b.closest('article');article.querySelector('.filtered').hidden=true;article.querySelector('.post-content').hidden=false;});
 const mark=id=>{if(!state.active)return;const p=posts.find(p=>p.id===id);if(!state.active.seen.some(x=>x.id===id))state.active.seen.push({id,category:p.category});};
 document.querySelectorAll('.read').forEach(b=>b.onclick=()=>{mark(b.dataset.id);save();b.textContent='✓ Read';b.classList.add('active');});
 document.querySelectorAll('.vote').forEach(b=>b.onclick=()=>{mark(b.dataset.id);const id=b.dataset.id,v=+b.dataset.value;state.active.feedback[id]=state.active.feedback[id]===v?0:v;save();const article=b.closest('article');article.querySelectorAll('.vote').forEach(x=>x.classList.toggle('active',+x.dataset.value===state.active.feedback[id]));const read=article.querySelector('.read');read.textContent='✓ Read';read.classList.add('active');});
 document.querySelectorAll('[data-category]').forEach(s=>s.onchange=()=>{state.preferences[s.dataset.category]=s.value;save();toast('Preference saved.');});
 if($('#export'))$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='steadier-my-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 if($('#delete'))$('#delete').onclick=()=>{$('#delete-confirm').innerHTML='<p class="note">Permanently delete check-ins, learned preferences, and any active session from this browser?</p><button class="secondary" id="cancel-delete">Cancel</button> <button class="primary" id="confirm-delete">Delete everything</button>';$('#cancel-delete').onclick=()=>$('#delete-confirm').replaceChildren();$('#confirm-delete').onclick=()=>{state=fresh();ending=false;try{localStorage.removeItem(key);storageOK=true;}catch{storageOK=false;}navigate('home');toast('Your local data has been deleted.');};};
}
$('#date').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>navigate(b.dataset.tab));render();
